<script setup lang="ts">
import { ref, watch, onMounted } from 'vue'
import { Save, ArrowUp, ArrowDown, ExternalLink } from '@lucide/vue'
import * as api from '../domain/api'
import type { Category } from '../domain/catalog'
const props = defineProps<{ categories: Category[]; editable: boolean; categoryId: number | null }>(); const emit = defineEmits<{ changed: [] }>()
const category = ref(props.categoryId ?? props.categories[0]?.id ?? 0); const settings = ref<api.FilterSettings | null>(null); const error = ref(''); const busy = ref(false); const message = ref(''); let generation=0
async function load() { const n=++generation; busy.value=true; error.value=''; message.value=''; try { const data=await api.getFilters(category.value); if(n===generation)settings.value=data } catch(e){if(n===generation)error.value=e instanceof Error?e.message:'Ошибка загрузки'} finally {if(n===generation)busy.value=false} }
watch(category,load);onMounted(load)
function toggle(label: string) { if(!settings.value)return; settings.value.selected=settings.value.selected.includes(label)?settings.value.selected.filter(x=>x!==label):[...settings.value.selected,label] }
function move(i:number,delta:number){const a=settings.value?.selected;if(!a||i+delta<0||i+delta>=a.length)return;[a[i],a[i+delta]]=[a[i+delta]!,a[i]!]}
async function save(inherit=false){if(!settings.value||busy.value)return;busy.value=true;error.value='';try{settings.value=await api.saveFilters(category.value,settings.value,inherit);message.value='Набор фильтров сохранён на тестовом сайте.';emit('changed')}catch(e){error.value=e instanceof Error?e.message:'Не удалось сохранить'}finally{busy.value=false}}
</script>
<template><section><div class="page-heading"><div><h1>Фильтры каталога</h1><p>Какие характеристики показывать покупателю в каждом разделе</p></div></div><label class="category-picker">Раздел каталога<select v-model="category"><option v-for="c in categories" :key="c.id" :value="c.id">{{ c.name }}</option></select></label><p v-if="error" class="error-notice" role="alert">{{ error }}</p><p v-if="message" class="success-notice" role="status">{{ message }}</p><div v-if="settings" class="editor-grid"><div><h2>Доступные характеристики</h2><p class="muted">Только поля опубликованных товаров этого раздела и подразделов. Гарантии, срок службы и изображения исключены.</p><div class="facet-picks"><label v-for="label in settings.available" :key="label"><input type="checkbox" :checked="settings.selected.includes(label)" :disabled="!editable||busy" @change="toggle(label)" />{{ label }}</label></div><p v-if="!settings.available.length" class="muted">У опубликованных товаров нет доступных характеристик.</p></div><aside class="editor-aside"><h2>Порядок в фильтре</h2><p class="muted">{{ settings.explicit ? 'Индивидуальный набор раздела' : 'Наследуемый или стандартный набор' }}</p><div class="term-list"><article v-for="(label,i) in settings.selected" :key="label"><span>{{ i+1 }}. {{ label }}</span><button class="icon-button" :disabled="!editable||busy||i===0" :aria-label="`Поднять ${label}`" @click="move(i,-1)"><ArrowUp :size="15" /></button><button class="icon-button" :disabled="!editable||busy||i===settings.selected.length-1" :aria-label="`Опустить ${label}`" @click="move(i,1)"><ArrowDown :size="15" /></button></article></div><p v-if="!settings.selected.length" class="info-box">Будет показан только диапазон цены. Характеристики товаров не удаляются.</p><a :href="settings.url" target="_blank" rel="noopener noreferrer" class="text-button">Открыть раздел на тесте <ExternalLink :size="15" /></a></aside></div><div v-if="settings&&editable" class="modal-actions"><button class="button" :disabled="busy" @click="save(true)">Вернуть наследуемый набор</button><button class="button primary" :disabled="busy" @click="save()"><Save :size="17" />{{ busy?'Сохраняем…':'Сохранить набор' }}</button></div></section></template>
